import sys
from types import ModuleType

# Mock reportlab modules if not installed so that tests pass in isolated environments without network access
if "reportlab" not in sys.modules:
    rl = ModuleType("reportlab")
    sys.modules["reportlab"] = rl

    lib = ModuleType("reportlab.lib")
    sys.modules["reportlab.lib"] = lib

    pagesizes = ModuleType("reportlab.lib.pagesizes")
    pagesizes.letter = (612, 792)
    sys.modules["reportlab.lib.pagesizes"] = pagesizes

    pdfgen = ModuleType("reportlab.pdfgen")
    sys.modules["reportlab.pdfgen"] = pdfgen

    class MockCanvas:
        def __init__(self, path, pagesize=None):
            self.path = path
            self.pagesize = pagesize

        def drawString(self, x, y, text):
            pass

        def showPage(self):
            pass

        def save(self):
            with open(self.path, "wb") as f:
                f.write(b"%PDF-1.4 mock")

    pdfgen.canvas = ModuleType("reportlab.pdfgen.canvas")
    pdfgen.canvas.Canvas = MockCanvas

