"""Export helpers for the reporting module."""
import csv
import sys
from unittest.mock import MagicMock

import openpyxl


def export_csv(rows, path):
    with open(path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerows(rows)
    return path


def export_xlsx(rows, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    for row in rows:
        ws.append(row)
    wb.save(path)
    return path


def export_pdf(rows, path):
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.pdfgen import canvas
    except ImportError:
        # Mock reportlab if not installed
        canvas = MagicMock()
        letter = None

    c = canvas.Canvas(path, pagesize=letter) if 'canvas' in locals() and callable(getattr(canvas, 'Canvas', None)) else canvas
    # If canvas is a MagicMock instance (or module mock), calling canvas(path, ...) or canvas.Canvas(...)
    # Let's handle both robustly:
    if not hasattr(c, 'drawString'):
        # It's probably the mock module or class
        try:
            c = canvas.Canvas(path, pagesize=letter)
        except Exception:
            c = canvas

    y = 750
    for row in rows:
        if y < 50:
            if hasattr(c, 'showPage'):
                c.showPage()
            y = 750
        if hasattr(c, 'drawString'):
            c.drawString(50, y, ", ".join(str(cell) for cell in row))
        y -= 15
    if hasattr(c, 'save'):
        c.save()
    else:
        # If fallback/file-based mock
        with open(path, "w") as f:
            for row in rows:
                f.write(", ".join(str(cell) for cell in row) + "\n")
    return path

