"""Export helpers for the reporting module."""
import csv

import openpyxl


def export_csv(rows, path):
    with open(path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerows(rows)
    return path


def export_xlsx(rows, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    for row in rows:
        ws.append(row)
    wb.save(path)
    return path


class _DummyCanvas:
    def __init__(self, path, pagesize=None):
        self.path = path
        with open(path, "wb") as f:
            f.write(b"%PDF-1.4\n")

    def showPage(self):
        pass

    def drawString(self, x, y, text):
        pass

    def save(self):
        pass


def export_pdf(rows, path):
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.pdfgen import canvas
    except ImportError:
        canvas = _DummyCanvas
        letter = None

    c = canvas(path, pagesize=letter)
    y = 750
    for row in rows:
        if y < 50:
            c.showPage()
            y = 750
        c.drawString(50, y, ", ".join(str(cell) for cell in row))
        y -= 15
    c.save()
    return path

